create or replace function public.invite_enterprise_partner(p_network_id uuid,p_partner_business_id uuid) returns public.enterprise_partner_network_members language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare n public.enterprise_partner_networks; m public.enterprise_partner_network_members; begin select * into n from public.enterprise_partner_networks where id=p_network_id; if not found then raise exception 'network unavailable'; end if; if not exists(select 1 from public.business_members where business_id=n.owner_business_id and user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Enterprise partner admin access required'; end if; if not exists(select 1 from public.businesses where id=n.owner_business_id and lower(business_tier::text) in ('fleet','enterprise')) then raise exception 'Fleet or Enterprise plan required'; end if; if not exists(select 1 from public.businesses where id=p_partner_business_id) then raise exception 'partner business unavailable'; end if; insert into public.enterprise_partner_network_members(network_id,partner_business_id,status) values(n.id,p_partner_business_id,'invited') on conflict(network_id,partner_business_id) do update set status='invited' returning * into m; return m; end $$;
